def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def fibonacci(n):
    if n <= 1:
        return n
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def sum_of_digits(n):
    if n == 0:
        return 0
    else:
        return (n % 10) + sum_of_digits(n // 10)

def power_slow(x, n):
    if n == 0:
        return 1
    else:
        return x * power_slow(x, n - 1)

def power_fast(x, n):
    if n == 0:
        return 1
    elif n % 2 == 0:
        half = power_fast(x, n // 2)
        return half * half
    else:
        half = power_fast(x, (n - 1) // 2)
        return x * half * half
